236	    /**
237	     * Return the Pet with the given name, or null if none found for this Owner.
238	     *
239	     * @param name to test
240	     * @return true if pet name is already in use
241	     */
242	    public Pet getPet(String name, boolean ignoreNew) {
243	        name = name.toLowerCase();
244	        for (Pet pet : getPetsInternal()) {
245	            if (!ignoreNew || !pet.isNew()) {
246	                String compName = pet.getName();
247	                compName = compName.toLowerCase();
248	                if (compName.equals(name)) {
249	                    return pet;
250	                }
251	            }
252	        }
253	        return null;
254	    }
