1	package org.springframework.samples.petclinic.model;
2	
3	import java.util.Map;
4	import java.util.regex.Pattern;
5	
6	/**
7	 * Validates a 4-digit postcode against the fixed region ranges derived from an owner's
8	 * city (see {@link Locality}): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A city with
9	 * no known region accepts any 4-digit postcode.
10	 */
11	public final class Postcode {
12	
13	    /** A postcode must be exactly four digits. */
14	    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");
15	
16	    /** Region -> inclusive 4-digit postcode range {low, high}. */
17	    private static final Map<String, int[]> REGION_RANGE = Map.of(
18	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
19	
20	    private Postcode() {
21	    }
22	
23	    /**
24	     * Whether {@code postcode} is valid for {@code city}: it must be exactly four digits and,
25	     * when the city maps to a known region, fall within that region's inclusive range. A city
26	     * with no known region accepts any 4-digit postcode.
27	     */
28	    public static boolean isValidForCity(String postcode, String city) {
29	        if (postcode == null || !FOUR_DIGITS.matcher(postcode).matches()) {
30	            return false;
31	        }
32	        int[] range = REGION_RANGE.get(Locality.of(city));
33	        if (range == null) {
34	            return true;
35	        }
36	        int value = Integer.parseInt(postcode);
37	        return value >= range[0] && value <= range[1];
38	    }
39	}
